// One item per invoice attachment: PDF, PNG, JPEG or TIFF.
// Small images are skipped because they are usually logos or signatures from the email body.
const MIN_IMAGE_BYTES = 30 * 1024;
const out = [];
const emails = $input.all();

for (let index = 0; index < emails.length; index++) {
  const email = emails[index];
  const j = email.json || {};
  const from = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || (j.from && j.from.text) || (typeof j.from === 'string' ? j.from : '');
  const received = j.date ? new Date(j.date) : null;

  for (const [key, bin] of Object.entries(email.binary || {})) {
    const name = String(bin.fileName || key);
    const mime = String(bin.mimeType || '').toLowerCase();
    const isPdf = mime === 'application/pdf' || /\.pdf$/i.test(name);
    const isImage = /^image\/(png|jpeg|jpg|tiff)$/.test(mime) || /\.(png|jpe?g|tiff?)$/i.test(name);
    if (!isPdf && !isImage) continue;
    if (isImage) {
      const buffer = await this.helpers.getBinaryDataBuffer(index, key);
      if (buffer.length < MIN_IMAGE_BYTES) continue;
    }
    out.push({
      json: {
        'Received': received && !isNaN(received) ? received.toISOString().slice(0, 16).replace('T', ' ') : '',
        'From': from,
        'Subject': j.subject || '',
        'File': name,
      },
      binary: { invoice: bin },
      pairedItem: { item: index },
    });
  }
}

return out;

// Reads the answer of "Extract invoice data" or "Check job status" and builds one sheet row.
// Status: Extracted | Needs review (required fields missing) | Processing (checked again) | Failed
const MAX_CHECKS = 30; // 30 checks × 10 s = 5 more minutes after the first answer

const email = $('Split attachments').item.json;
const res = $json || {};
const httpCode = Number(res.statusCode || 0);
let body = res.body !== undefined ? res.body : res;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = { message: body.slice(0, 300) }; }
}
body = body || {};

if (httpCode === 401 || httpCode === 403) {
  throw new Error('PaperOffice AI rejected the API key (HTTP ' + httpCode + '). Create a User token (po_ut_…) under Account → API and put it into the "PaperOffice AI" credential.');
}

const row = {
  'Received': email['Received'],
  'From': email['From'],
  'Subject': email['Subject'],
  'File': email['File'],
  'Status': '',
  'Supplier': '',
  'Supplier VAT ID': '',
  'Invoice number': '',
  'Invoice date': '',
  'Due date': '',
  'Net amount': '',
  'VAT amount': '',
  'Total amount': '',
  'Currency': '',
  'IBAN': '',
  'Payment terms': '',
  'Line items': '',
  'Missing fields': '',
  'Job ID': String(body.job_id || ''),
  'Note': '',
};

const jobStatus = String(body.job_status || '').toLowerCase();
const failed = httpCode >= 400 || body.status === 'error' || ['failed', 'error', 'cancelled'].includes(jobStatus);
if (failed) {
  row['Status'] = 'Failed';
  row['Note'] = [body.error_code || body.code, body.message || body.error || ('HTTP ' + httpCode)].filter(Boolean).join(': ');
  return { json: row };
}

const payload = body.result || body.job_result || {};
const pages = Array.isArray(payload.pages_idp) ? payload.pages_idp : [];
const finished = ['completed', 'done'].includes(jobStatus) || pages.length > 0;

if (!finished) {
  if (!row['Job ID']) {
    row['Status'] = 'Failed';
    row['Note'] = 'No job ID in the answer (HTTP ' + httpCode + ').';
  } else if ($runIndex >= MAX_CHECKS) {
    row['Status'] = 'Failed';
    row['Note'] = 'Still running after ' + MAX_CHECKS + ' checks. Look up the job ID later with GET /job/get/{job_id}.';
  } else {
    row['Status'] = 'Processing';
  }
  return { json: row };
}

// suggested_fields is either an object keyed by field or an array of { key | category, value, value_raw }
function rawField(key) {
  for (const page of pages) {
    const sf = page && page.suggested_fields;
    if (!sf) continue;
    const f = Array.isArray(sf) ? sf.find((x) => x && (x.key === key || x.category === key)) : sf[key];
    if (f === undefined || f === null) continue;
    const value = typeof f === 'object' ? f.value : f;
    if (value === 'VALUE_MISSING') continue;
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return { value, raw: typeof f === 'object' && f.value_raw !== undefined && f.value_raw !== null ? f.value_raw : value };
    }
  }
  return null;
}
const text = (key) => { const f = rawField(key); return f ? String(f.value).trim() : ''; };
// value_raw is machine-readable: ISO date, amount with a dot as decimal separator
const date = (key) => { const f = rawField(key); return f ? String(f.raw).trim() : ''; };
const amount = (key) => {
  const f = rawField(key);
  if (!f) return '';
  const raw = String(f.raw).trim();
  const m = /^(-?\d+(?:\.\d+)?)(?:\s*[A-Z]{3})?$/.exec(raw);
  return m ? Number(m[1]) : String(f.value).trim();
};

const positions = (rawField('_line_items') || {}).value;
const lineItems = Array.isArray(positions)
  ? positions.map((it) => [it.quantity, it.description, it.total_price_net].filter((v) => v !== undefined && v !== null && String(v).trim() !== '').join(' · ')).join('\n')
  : (positions ? String(positions) : '');
const missing = Number(pages[0] && pages[0].__document__data__idp__missing_required_count) || 0;

// Plausibility: net + VAT must match the total (1 cent tolerance per amount for rounding)
const net = amount('_net_amount'); const vat = amount('_vat_amount'); const total = amount('_total_amount');
const sumOff = typeof net === 'number' && typeof vat === 'number' && typeof total === 'number' && Math.abs(net + vat - total) > 0.02;

Object.assign(row, {
  'Status': missing > 0 || sumOff ? 'Needs review' : 'Extracted',
  'Note': sumOff ? 'Net ' + net.toFixed(2) + ' + VAT ' + vat.toFixed(2) + ' does not match the total ' + total.toFixed(2) + '.' : '',
  'Supplier': text('_supplier_name'),
  'Supplier VAT ID': text('_supplier_vat_id'),
  'Invoice number': text('_invoice_number'),
  'Invoice date': date('_invoice_date'),
  'Due date': date('_payment_due_date'),
  'Net amount': net,
  'VAT amount': vat,
  'Total amount': total,
  'Currency': text('_currency'),
  'IBAN': text('_creditor_iban'),
  'Payment terms': text('_payment_terms'),
  'Line items': lineItems,
  'VAT breakdown': (() => { const b = (rawField('_vat_breakdown') || {}).value; return Array.isArray(b) ? b : []; })(),
  'Missing fields': missing,
});
return { json: row };

// Marks repeats of an invoice: same supplier and invoice number as an invoice this workflow already created
// in the accounting system (remembered in "Result", active runs only, last 5,000), or as an earlier file in this run.
const seen = $getWorkflowStaticData('global');
seen.invoices = seen.invoices || {};
const thisRun = {};
// Letters and digits of any script; spaces, dashes and dots do not count
const norm = (v) => String(v || '').normalize('NFKC').toLocaleUpperCase().replace(/[^\p{L}\p{N}]/gu, '');
return $input.all().map((item) => {
  const row = { ...item.json };
  const supplier = norm(row['Supplier']);
  const number = norm(row['Invoice number']);
  if (['Extracted', 'Needs review'].includes(row['Status']) && supplier && number) {
    const key = supplier + '|' + number;
    const first = seen.invoices[key] || thisRun[key];
    if (first) {
      row['Status'] = 'Duplicate';
      row['Note'] = 'Already sent from "' + first.file + '" (' + first.received + ').' + (row['Note'] ? ' ' + row['Note'] : '');
    } else {
      thisRun[key] = { file: row['File'], received: row['Received'] };
    }
  }
  return { json: row, pairedItem: item.pairedItem };
});

// Builds the Lexware Office voucher from the extracted row and decides whether it can be sent.
// Booking category for the VAT lines; preset: "Sonstige Ausgaben". Other IDs: GET https://api.lexware.io/v1/posting-categories
// The category is checked by a person anyway, because every voucher stays "to be checked".
const CATEGORY_ID = '16d04a28-fd91-11e1-a21f-0800200c9a66';
const LEXWARE_TAX_RATES = [0, 5, 7, 16, 19];

const row = { ...$json };
const out = { ...row, 'Lexware voucher': '', 'Lexware link': '' };
const pass = (status, note) => ({ json: { ...out, 'Status': status, 'Note': [note, row['Note']].filter(Boolean).join(' '), send: false } });

if (!['Extracted', 'Needs review'].includes(row['Status'])) return { json: { ...out, send: false } };
// Missing optional fields only mark the row; amounts that do not add up are never sent
if (row['Status'] === 'Needs review' && /does not match the total/.test(row['Note'] || '')) return pass('Needs review', 'Not sent to Lexware Office.');

const currency = String(row['Currency'] || 'EUR').toUpperCase();
if (currency !== 'EUR') return pass('Needs review', 'Currency ' + currency + ': Lexware Office vouchers are EUR only. Not sent.');
const number = String(row['Invoice number'] || '').trim();
if (!number) return pass('Needs review', 'No invoice number, so the duplicate check in Lexware Office is not possible. Not sent.');
const total = row['Total amount'];
if (typeof total !== 'number') return pass('Needs review', 'No readable total amount. Not sent.');

const r2 = (v) => Math.round(Math.abs(Number(v) || 0) * 100) / 100;
const isDate = (v) => /^\d{4}-\d{2}-\d{2}/.test(String(v || ''));
const vat = typeof row['VAT amount'] === 'number' ? row['VAT amount'] : 0;

const voucher = {
  type: total < 0 ? 'purchasecreditnote' : 'purchaseinvoice',
  voucherStatus: 'unchecked',
  voucherNumber: number.slice(0, 255),
  totalGrossAmount: r2(total),
  totalTaxAmount: r2(vat),
  taxType: 'gross',
  useCollectiveContact: true,
  remark: ('Read by PaperOffice AI from "' + row['File'] + '" (job ' + row['Job ID'] + '). Please check before booking.').slice(0, 1000),
};
if (row['Supplier']) voucher.contactName = String(row['Supplier']).slice(0, 255);
if (isDate(row['Invoice date'])) voucher.voucherDate = String(row['Invoice date']).slice(0, 10);
if (isDate(row['Due date'])) voucher.dueDate = String(row['Due date']).slice(0, 10);

{
  // Lexware needs VAT lines whenever amounts are sent: one gross line per VAT rate, the totals are the sums of the lines.
  const parts = (row['VAT breakdown'] || [])
    .map((b) => ({ rate: Number(b.rate_percent), net: Number(b.taxable_base_net ?? b.net_amount), tax: Number(b.vat_amount) }))
    .filter((b) => Number.isFinite(b.rate) && Number.isFinite(b.net) && Number.isFinite(b.tax));
  const lines = parts.length
    ? parts.map((b) => ({ rate: b.rate, gross: r2(b.net + b.tax), tax: r2(b.tax) }))
    : (typeof row['Net amount'] === 'number' && row['Net amount'] !== 0
      ? [{ rate: Math.round((vat / row['Net amount']) * 100), gross: r2(total), tax: r2(vat) }]
      : []);
  const valid = lines.length && lines.every((l) => LEXWARE_TAX_RATES.includes(l.rate));
  const sum = lines.reduce((s, l) => s + l.gross, 0);
  if (valid && Math.abs(sum - r2(total)) <= 0.02) {
    voucher.voucherItems = lines.map((l) => ({ amount: l.gross, taxAmount: l.tax, taxRatePercent: l.rate, categoryId: CATEGORY_ID }));
    voucher.totalGrossAmount = r2(lines.reduce((s, l) => s + l.gross, 0));
    voucher.totalTaxAmount = r2(lines.reduce((s, l) => s + l.tax, 0));
  } else {
    // Without valid lines Lexware rejects the totals: send number, dates and file only
    delete voucher.totalGrossAmount;
    delete voucher.totalTaxAmount;
    out['Status'] = 'Needs review';
    out['Note'] = [out['Note'], 'Amounts not sent (VAT rate not supported by Lexware or lines do not add up); please enter them in Lexware Office.'].filter(Boolean).join(' ');
  }
}

return { json: { ...out, send: true, voucher } };

// Lexware voucher list answer: same invoice number already there → Duplicate, otherwise create the voucher.
const row = { ...$('Build Lexware voucher').item.json };
const res = $json || {};
const code = Number(res.statusCode || 0);
if (code === 401 || code === 403) {
  throw new Error('Lexware Office rejected the API key (HTTP ' + code + '). Create a private API key at https://app.lexware.de/addons/public-api and put it into the Lexware credential.');
}
if (code !== 200) {
  return { json: { ...row, 'Status': 'Failed', 'Note': 'Lexware voucher list answered HTTP ' + code + '. Not sent.', send: false } };
}
const norm = (v) => String(v || '').normalize('NFKC').toLocaleUpperCase().replace(/[^\p{L}\p{N}]/gu, '');
const content = (res.body && Array.isArray(res.body.content)) ? res.body.content : [];
// Same invoice number and the same supplier (a missing name on either side does not count as different)
const sameName = (a, b) => !norm(a) || !norm(b) || norm(a) === norm(b);
const same = content.find((v) => norm(v.voucherNumber) === norm(row['Invoice number']) && sameName(v.contactName, row['Supplier']));
if (same) {
  return { json: { ...row, 'Status': 'Duplicate', 'Note': 'Invoice number already in Lexware Office (' + same.voucherStatus + ').', 'Lexware voucher': same.id, 'Lexware link': 'https://app.lexware.de/permalink/vouchers/view/' + same.id, send: false } };
}
return { json: { ...row, send: true } };

// Answer of "Create voucher": keep the voucher ID and add the original file again for the upload.
const row = { ...$('Already in Lexware?').item.json };
const res = $json || {};
const code = Number(res.statusCode || 0);
const id = res.body && res.body.id;
if (code === 401 || code === 403) {
  throw new Error('Lexware Office rejected the API key (HTTP ' + code + ').');
}
if (!code || code >= 500 || res.error) {
  // Timeout or server error: the voucher may exist. Never send again automatically.
  return { json: { ...row, 'Status': 'Uncertain', 'Note': 'Lexware Office did not confirm the voucher (HTTP ' + (code || 'timeout') + '). Check Lexware Office before sending it again.', send: false } };
}
if (code >= 400 || !id) {
  const msg = res.body && (res.body.message || (res.body.details && JSON.stringify(res.body.details)));
  return { json: { ...row, 'Status': 'Failed', 'Note': 'Lexware Office rejected the voucher (HTTP ' + code + ')' + (msg ? ': ' + String(msg).slice(0, 300) : '.'), send: false } };
}
return {
  json: { ...row, 'Status': row['Status'] === 'Needs review' ? 'Needs review' : 'Created', 'Lexware voucher': id, 'Lexware link': 'https://app.lexware.de/permalink/vouchers/view/' + id, send: true },
  binary: $('Split attachments').item.binary,
};

// One line per invoice (runs per item): status, note and the link to the voucher in Lexware Office.
const j = $json || {};
let row = j;
if (j.statusCode !== undefined || j.error !== undefined) {
  // Answer of "Attach original file" (also a network error): the matching invoice row of this item
  row = { ...$('Add original file').item.json };
  const code = Number(j.statusCode || 0);
  if (code < 200 || code >= 300) {
    row['Status'] = 'Needs review';
    row['Note'] = [row['Note'], 'Voucher created, but the file was not attached (HTTP ' + (code || 'timeout') + '). Attach it in Lexware Office.'].filter(Boolean).join(' ');
  }
}
const { send, voucher, ...out } = row;
remember(out, out['Lexware voucher']);
return { json: out };

function remember(row, targetId) {
  if (!targetId) return;
  const norm = (v) => String(v || '').normalize('NFKC').toLocaleUpperCase().replace(/[^\p{L}\p{N}]/gu, '');
  const supplier = norm(row['Supplier']);
  const number = norm(row['Invoice number']);
  if (!supplier || !number) return;
  const seen = $getWorkflowStaticData('global');
  seen.invoices = seen.invoices || {};
  seen.invoices[supplier + '|' + number] = { file: row['File'], received: row['Received'] };
  const keys = Object.keys(seen.invoices);
  for (let i = 0; i < keys.length - 5000; i++) delete seen.invoices[keys[i]];
}
